<script setup lang="ts">
import { ref,onMounted,onUnmounted } from 'vue';import { request,post } from './client';import { t } from './i18n';import { isAdmin } from './permissions';import { notificationTime,notificationLabel,type NotificationDelivery } from './notifications';import ResourceTable from './ResourceTable.vue';import Modal from './Modal.vue';
const deliveries=ref<NotificationDelivery[]>([]),state=ref(''),busy=ref(false),error=ref(''),next=ref<number|null>(null),total=ref(0),selected=ref<NotificationDelivery|null>(null);let live=true;
async function load(more=false){if(busy.value)return;busy.value=true;error.value='';try{const r=await request(`/notifications/deliveries?state=${state.value}&offset=${more?next.value||0:0}&limit=100`);if(live){deliveries.value=more?[...deliveries.value,...r.deliveries]:r.deliveries;next.value=r.nextOffset??null;total.value=r.total;}}catch(e){if(live)error.value=String(e);}finally{if(live)busy.value=false;}}
async function retry(){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{await post('/notifications/deliveries/'+selected.value.id+'/retry',{});if(live)selected.value=null;}catch(e){if(live)error.value=String(e);}finally{if(live)busy.value=false;}if(!error.value)await load();}
onMounted(()=>load());onUnmounted(()=>{live=false;});
</script>
<template><section class="panel"><header><h2>{{ t('История доставки') }}</h2><button :disabled="busy" @click="load()">{{ t('Обновить') }}</button></header><p class="footnote">{{ t('В очереди не означает доставлено. Неподтверждённая доставка могла дойти до получателя.') }}</p><div class="toolbar"><label>{{ t('Состояние доставки') }}<select :disabled="busy" v-model="state" @change="load()"><option value="">{{ t('Все') }}</option><option v-for="value in ['pending','sending','sent','retrying','failed','uncertain','suppressed']" :key="value" :value="value">{{ notificationLabel(value) }}</option></select></label></div><p v-if="error" class="notice error" role="alert">{{ error }}</p><div v-if="busy&&!deliveries.length" class="loading-state">{{ t('Загрузка…') }}</div><ResourceTable v-else :rows="deliveries.map(d=>({...d,statusLabel:notificationLabel(d.state),time:notificationTime(d.createdAt)}))" :empty="t('Нет доставок по выбранным фильтрам')" :columns="[{key:'id',title:'ID'},{key:'statusLabel',title:t('Состояние')},{key:'channelId',title:t('Канал')},{key:'attempts',title:t('Попытки')},{key:'time',title:t('Время')},{key:'errorCode',title:t('Ошибка')}]" @select="selected=$event" /><div class="toolbar"><span>{{ deliveries.length }} / {{ total }}</span><button v-if="next!==null" :disabled="busy" @click="load(true)">{{ t('Загрузить ещё') }}</button></div></section><Modal v-if="selected" :title="t('Доставка')" @close="selected=null"><dl class="detail-grid"><dt>ID</dt><dd>{{ selected.id }}</dd><dt>{{ t('Состояние') }}</dt><dd>{{ notificationLabel(selected.state) }}</dd><dt>{{ t('Канал') }}</dt><dd>{{ selected.channelId }}</dd><dt>{{ t('Попытки') }}</dt><dd>{{ selected.attempts }}</dd><dt>{{ t('Последняя попытка') }}</dt><dd>{{ notificationTime(selected.lastAttemptAt) }}</dd><dt>{{ t('Ошибка') }}</dt><dd>{{ selected.errorCode||'—' }}</dd></dl><template v-if="isAdmin&&['failed','uncertain'].includes(selected.state)"><p class="notice warning">{{ t('Повтор может отправить дубликат. Подтвердите ручную повторную доставку.') }}</p><p v-if="error" class="notice error">{{ error }}</p><button :disabled="busy" @click="retry">{{ t('Подтвердить повтор') }}</button></template></Modal></template>
